   "id": "g_articles",
   "title_tr": "a / an / the (artikeller)",
   "title_en": "Articles: a / an / the",
   "level": "A1",
   "order": 4,
   "explain_md": "Türkçede 'bir' kelimesi isteğe bağlıdır: 'Ben tasarımcıyım' da olur, 'Ben bir tasarımcıyım' da. İngilizcede **tekil sayılabilir bir isim yalnız kalamaz**; önünde mutlaka bir şey olur: `a`, `an`, `the`, `my`, `this` gibi. Bu yüzden ✗ `I am designer.` yanlış, ✓ `I am **a** designer.` doğrudur.\n\n**a / an = bir** (belirsiz, herhangi bir). Seçim **sese** göre: sonraki kelime ünsüz **sesle** başlıyorsa `a` (a designer, a car, a university — 'yu' sesi), ünlü **sesle** başlıyorsa `an` (an apple, an email, an hour — h sessiz).\n\n**the = o bilinen** (belirli). Türkçede karşılığı yoktur; bu yüzden en zor olanıdır. Mantık şu: dinleyen **hangisinden** bahsettiğini biliyorsa `the`. `I have a client. The client is from Germany.` — ilk geçişte a (yeni bilgi), ikinci geçişte the (artık biliyoruz). Tek olan şeyler de the alır: the sun, the office (bizim ofis), the boss.\n\n**Artikel yok:** çoğul ve sayılamayan isimler genel anlamda (`I like coffee.` `Designers are busy.`), şehir ve çoğu ülke adı (Samsun, Turkey; ama the USA, the UK), yemek öğünleri (have breakfast), diller (I speak English).\n\n**Meslek önünde a şart:** `She's a teacher.` `He's an engineer.`\n\n**Türk öğrenci tuzakları:** (1) a'yı sayı sanıp atlamak: 'bir' demiyorum ki, diye `a` düşürülür. (2) `the`yi her yere koymak: ✗ the Istanbul, ✗ the Turkey. (3) a/an'ı harfe göre seçmek: ✗ an university, ✗ a hour.",
