   "id": "g_prepositions_place",
   "title_tr": "Yer edatları: in / on / at / under / next to",
   "title_en": "Prepositions of place",
   "level": "A1",
   "order": 19,
   "explain_md": "Türkçede 'nerede' sorusunun cevabı tek ektir: -de/-da ('masa**da**', 'ofis**te**', 'Samsun'**da**'). İngilizce bu tek eki birkaç kelimeye böler; bu yüzden Türk öğrenci için en zor konulardan biridir. Mantığını öğrenirsen çoğu yerinde oturur:\n\n- **in** → **içinde** (kapalı alan, kutu, şehir, ülke): `in the box`, `in the office`, `in Samsun`, `in Turkey`, `in the car`, `in the kitchen`\n- **on** → **üstünde, temas halinde** (yüzey): `on the desk`, `on the wall`, `on the floor`, `on the bus` (ayakta durulan taşıtlar: bus, train, plane)\n- **at** → **noktada** (yer bir nokta gibi düşünülür): `at the office` (işte), `at home`, `at school`, `at the door`, `at the bus stop`, `at the party`\n\n`in the office` (ofisin fiziksel içinde) ve `at the office` (işte, çalışıyor) ikisi de olur; `at` daha çok 'orada bulunuyor' anlamı taşır. `at home` sabittir (✗ in home).\n\n**Diğerleri:**\n- **under** → altında: `under the desk`\n- **next to** → yanında: `next to the window`\n- **behind** → arkasında: `behind the door`\n- **in front of** → önünde: `in front of the building`\n- **between** → arasında (iki şey): `between the bank and the café`\n- **opposite** → karşısında: `opposite the station`\n- **near** → yakınında: `near the sea`\n\n**Yol tarifi:** `Where's the bank? — It's on the left / on the right. It's next to the pharmacy. Go straight. Turn left at the corner.`\n\n**Yön fiilleriyle (to):** gitmek → `go to work`, `go to the office`, `go to Istanbul`. İstisna: `go home` (✗ go to home), `go there`, `go downstairs`.\n\n**Tuzaklar:** ✗ `in the desk` (masanın içinde?) ✓ `on the desk`; ✗ `at Samsun` ✓ `in Samsun`; ✗ `go to home` ✓ `go home`; ✗ `in the bus` ✓ `on the bus`.",
